from mb_sefaria import sef_header
from mb_misc import ws_urls


class WsUrlsEncodingTests(unittest.TestCase):
    def test_hebrew_root_url_shape(self):
        self.assertEqual(
            ws_urls.HEBREW,
            "https://he.wikisource.org/wiki/%D7%9E%D7%A7%D7%A8%D7%90_%D7%A2%D7%9C_%D7%A4%D7%99_"
            "%D7%94%D7%9E%D7%A1%D7%95%D7%A8%D7%94",
        )

    def test_introduction_and_report_urls(self):
        self.assertEqual(
            sef_header._INTRODUCTION_URL,
            "https://he.wikisource.org/wiki/%D7%95%D7%99%D7%A7%D7%99%D7%98%D7%A7%D7%A1%D7%98:"
            "%D7%9E%D7%91%D7%95%D7%90_%D7%9C%D7%9E%D7%A7%D7%A8%D7%90_%D7%A2%D7%9C_%D7%A4%D7%99_"
            "%D7%94%D7%9E%D7%A1%D7%95%D7%A8%D7%94",
        )
        self.assertEqual(
            sef_header._REPORT_URL,
            "https://he.wikisource.org/wiki/%D7%A9%D7%99%D7%97%D7%AA_%D7%9E%D7%A9%D7%AA%D7%9E%D7%A9:Dovi",
        )

    def test_rocc_anchor_still_uses_expected_url(self):
        expected_url = (
            "https://he.wikisource.org/wiki/"
            "%D7%95%D7%99%D7%A7%D7%99%D7%98%D7%A7%D7%A1%D7%98:%D7%9E%D7%91%D7%95%D7%90_"
            "%D7%9C%D7%9E%D7%A7%D7%A8%D7%90_%D7%A2%D7%9C_%D7%A4%D7%99_%D7%94%D7%9E%D7%A1%D7%95%D7%A8%D7%94/"
            "%D7%A4%D7%A8%D7%A7_%D7%91#%D7%94%D7%A1%D7%91%D7%A8_%D7%A7%D7%A6%D7%A8_%D7%A2%D7%9C_"
            "%D7%A2%D7%99%D7%A6%D7%95%D7%91_%D7%94%D7%9E%D7%A7%D7%A8%D7%90_%D7%91%D7%9E%D7%94%D7%93%D7%95%D7%A8%D7%AA%D7%A0%D7%95"
        )
        self.assertEqual(
            rocc_util._Y_30_CHAP_2_ANC["attr"]["href"],
            expected_url,
        )


